// Extract subtasks → emit one item per platform with parsed JSON variant.
const d = $json;
const subtasks = d.subtasks || [];
const out = [];

for (const st of subtasks) {
  // Match platform from name like '[LINKEDIN] ...'
  const m = (st.name || '').match(/^\[([A-Z]+)\]/);
  const platform = m ? m[1].toLowerCase() : null;
  if (!platform) continue;

  // Pull JSON block from description
  const desc = st.description || st.text_content || '';
  const jsonMatch = desc.match(/```json\s*([\s\S]*?)```/);
  let variant = {};
  if (jsonMatch) {
    try { variant = JSON.parse(jsonMatch[1]); } catch (e) { variant = { error: 'parse_failed' }; }
  }

  out.push({
    json: {
      run_id: (desc.match(/Run:\s*`?([\w-]+)`?/) || [])[1] || 'unknown',
      parent_task_id: d.id,
      subtask_id: st.id,
      platform,
      variant,
      source_title: d.name.replace(/^\[Approval\]\s*/, '')
    }
  });
}

return out;

// Calculate next optimal posting slot per platform.
// Stagger schedule = better reach + avoids spam flags.
const d = $json;
const now = new Date();

const SCHEDULES = {
  linkedin:  { days: [2, 3, 4],       hour: 14, minute: 0  }, // Tue/Wed/Thu 9am EST = 14 UTC
  x:         { days: [1, 2, 3, 4, 5], hour: 16, minute: 0  }, // Daily 11am EST = 16 UTC
  facebook:  { days: [3, 5],          hour: 18, minute: 0  }, // Wed/Fri 1pm EST
  instagram: { days: [1, 3, 5],       hour: 16, minute: 0  }, // Mon/Wed/Fri 11am EST
  pinterest: { days: [6, 0],          hour: 1,  minute: 0  }, // Sat/Sun 8pm EST = 1 UTC next day
  gbp:       { days: [2],             hour: 15, minute: 0  }, // Tue 10am EST
  medium:    { days: [0],             hour: 14, minute: 0  }, // Sun 9am EST
  threads:   { days: [1, 2, 3, 4, 5], hour: 0,  minute: 0  }  // Daily 7pm EST = 0 UTC next day
};

const sched = SCHEDULES[d.platform];
if (!sched) {
  return [{ json: { ...d, scheduled_at: now.toISOString(), error: 'no_schedule_rule' } }];
}

// Find next valid slot
const candidate = new Date(now);
candidate.setUTCHours(sched.hour, sched.minute, 0, 0);
for (let i = 0; i < 14; i++) {
  const day = candidate.getUTCDay();
  if (sched.days.includes(day) && candidate.getTime() > now.getTime() + 30 * 60 * 1000) {
    break;
  }
  candidate.setUTCDate(candidate.getUTCDate() + 1);
}

return [{
  json: {
    ...d,
    scheduled_at: candidate.toISOString(),
    scheduled_unix_ms: candidate.getTime()
  }
}];

// Map our platform key to Postiz integration ID.
const integrations = $json || [];
const current = $('Calculate Optimal Slot').item.json;

// Postiz identifier mapping (these are typical names; adjust via env override).
const POSTIZ_KEYS = {
  linkedin:  ['linkedin', 'linkedin-page'],
  x:         ['x', 'twitter'],
  facebook:  ['facebook', 'facebook-page'],
  instagram: ['instagram', 'instagram-standalone'],
  pinterest: ['pinterest'],
  gbp:       ['google-business', 'google'],
  medium:    ['medium'],
  threads:   ['threads']
};

const targetKeys = POSTIZ_KEYS[current.platform] || [current.platform];
const match = (integrations || []).find(i =>
  targetKeys.includes((i.identifier || i.providerIdentifier || '').toLowerCase())
);

if (!match) {
  return [{ json: { ...current, __error: `No Postiz integration found for platform: ${current.platform}` } }];
}

return [{ json: { ...current, postiz_integration_id: match.id } }];

// Build Postiz post payload — schema matches Postiz self-hosted /api/posts.
const d = $json;
const v = d.variant || {};

// Common content fields per platform shape.
let content = '';
if (v.text)        content = v.text;
else if (v.caption)content = v.caption;
else if (v.body)   content = v.body;
else if (v.post)   content = v.post;
else if (v.thread && Array.isArray(v.thread)) content = v.thread.join('\n\n---\n\n');
else if (typeof v === 'string') content = v;
else content = JSON.stringify(v);

// Append source URL where appropriate (not X/Threads — they have inline links)
if (d.platform !== 'x' && d.platform !== 'threads' && d.platform !== 'medium' && v.cta_url) {
  content += '\n\n' + v.cta_url;
}

// Postiz expects an array of posts (for threads/carousels).
const posts = [];
if (d.platform === 'x' && v.thread && Array.isArray(v.thread)) {
  v.thread.forEach((tweet) => posts.push({ content: tweet, image: [] }));
} else {
  const imageRef = d.source_image || v.image_url ? [{ url: d.source_image || v.image_url }] : [];
  posts.push({ content, image: imageRef });
}

return [{
  json: {
    ...d,
    postiz_payload: {
      type: 'schedule',
      date: d.scheduled_at,
      shortLink: false,
      tags: ['wpistic-auto'],
      posts: [{
        integration: { id: d.postiz_integration_id },
        value: posts,
        group: d.run_id
      }]
    }
  }
}];

